import{_ as a,a0 as i,w as l,s as d,ao as p,I as s,x as t,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在RHEL / CentOS / 5.x / 6.x上用密码保护单用户模式 | LCTT x X-CMD","titleTemplate":false,"description":"在RHEL / CentOS / 5.x / 6.x上用密码保护单用户模式 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在RHEL / CentOS / 5.x / 6.x上用密码保护单用户模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在RHEL / CentOS / 5.x / 6.x上用密码保护单用户模式 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140811 Disable or Password Protect Single User Mode or RHEL ro CentOS ro 5.x ro 6.x","title":"在RHEL / CentOS / 5.x / 6.x上用密码保护单用户模式","tag":"201409","desc":""},"relativePath":"201409/20140811 Disable or Password Protect Single User Mode or RHEL ro CentOS ro 5.x ro 6.x.md","filePath":"[post].md"}'),x={name:"201409/20140811 Disable or Password Protect Single User Mode or RHEL ro CentOS ro 5.x ro 6.x.md"};function u(b,e,c,m,h,g){const o=i("Link");return l(),d("div",null,[e[13]||(e[13]=p(`<h1 id="在rhel-centos-5-x-6-x上用密码保护单用户模式" tabindex="-1">在RHEL / CentOS / 5.x / 6.x上用密码保护单用户模式 <a class="header-anchor" href="#在rhel-centos-5-x-6-x上用密码保护单用户模式" aria-label="Permalink to “在RHEL / CentOS / 5.x / 6.x上用密码保护单用户模式”">​</a></h1><p>大家好，如果您还没有使用密码保护单用户模式，这对你的Linux服务器会是一个很大的风险，所以在涉及到安全性时，使用密码保护单用户模式是非常重要的。</p><p>今天这篇文章我会向你展示如何在RHEL / CentOS 5.x 和 RHEL / CentOS 6.x上使用密码保护你的单用户模式。</p><p>请仔细地执行所给出的命令，不然你的系统将会无法正常启动。首先，我会请你先完整地读完，然后在尝试。请自己承担相应的后果:-)</p><p><img src="http://www.tejasbarot.com/wp-content/uploads//password-300x140.jpg" alt="Password Protect"></p><p><small>Password Protect</small></p><h3 id="_1-对于-rhel-centos-5-x" tabindex="-1">1. 对于 RHEL / CentOS 5.x <a class="header-anchor" href="#_1-对于-rhel-centos-5-x" aria-label="Permalink to “1. 对于 RHEL / CentOS 5.x”">​</a></h3><h4 id="_1-1-开始之前请先备份你的-etc-inittab" tabindex="-1">1.1 开始之前请先备份你的 /etc/inittab <a class="header-anchor" href="#_1-1-开始之前请先备份你的-etc-inittab" aria-label="Permalink to “1.1 开始之前请先备份你的 /etc/inittab”">​</a></h4><pre><code>cp /etc/inittab /etc/inittab.backup
</code></pre><p><strong>要使单用户模式受到密码保护，用root执行下面的命令 :-</strong></p><pre><code>[root@tejas-barot-linux ~]# sed -i &#39;1i  su:S:wait:/sbin/sulogin&#39; /etc/inittab
</code></pre><p><strong>这样你会看到像下面这样的</strong></p><pre><code>su:S:wait:/sbin/sulogin
# Default runlevel. The runlevels used by RHS are:
# 0 - halt (Do NOT set initdefault to this)
# 1 - Single user mode
# 2 - Multiuser, without NFS (The same as 3, if you do not have networking)
# 3 - Full multiuser mode
# 4 - unused
# 5 - X11
# 6 - reboot (Do NOT set initdefault to this)
#
id:3:initdefault:
</code></pre><p><em>NOTE: 如果你不想使用sed命令你可以在/etc/inittab 顶部加入 “su:S:wait:/sbin/sulogin”</em></p><h3 id="_2-对于-rhel-centos-6-x" tabindex="-1">2. 对于 RHEL / CentOS 6.x <a class="header-anchor" href="#_2-对于-rhel-centos-6-x" aria-label="Permalink to “2. 对于 RHEL / CentOS 6.x”">​</a></h3><h4 id="_2-1-开始之前请先备份你的-etc-inittab" tabindex="-1">2.1 开始之前请先备份你的 /etc/inittab#### <a class="header-anchor" href="#_2-1-开始之前请先备份你的-etc-inittab" aria-label="Permalink to “2.1 开始之前请先备份你的 /etc/inittab####”">​</a></h4><pre><code>cp /etc/sysconfig/init /etc/sysconfig/init.backup
</code></pre><h4 id="_2-2-要使单用户模式受到密码保护-用root执行下面的命令" tabindex="-1">2.2 要使单用户模式受到密码保护，用root执行下面的命令 :- <a class="header-anchor" href="#_2-2-要使单用户模式受到密码保护-用root执行下面的命令" aria-label="Permalink to “2.2 要使单用户模式受到密码保护，用root执行下面的命令 :-”">​</a></h4><pre><code>[root@tejas-barot-linux ~]# sed -i &#39;s/SINGLE=\\/sbin\\/sushell/SINGLE=\\/sbin\\/sulogin/&#39; /etc/sysconfig/init
</code></pre><p><strong>这样你会看到像下面这样的</strong></p><pre><code>SINGLE=/sbin/sulogin
</code></pre><p><em>注意 :- 如果你不想使用sed你可以在 /etc/sysconfig/init 中直接改成 “SINGLE=/sbin/sulogin”</em></p><p>享受Linux 😃 享受开源</p><hr>`,24)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),r(o,{href:"http://www.tejasbarot.com/2014/05/05/disable-password-protect-single-user-mode-rhel-centos-5-x-6-x/"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.tejasbarot.com/2014/05/05/disable-password-protect-single-user-mode-rhel-centos-5-x-6-x/",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("作者：",-1)),r(o,{href:"https://plus.google.com/+TejasBarot"},{default:n(()=>[...e[2]||(e[2]=[t("Tejas Barot",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:n(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),r(o,{href:"http://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const L=a(x,[["render",u]]);export{C as __pageData,L as default};
